package com.gamerparadise.activity;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestHeader;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.HttpHeaders;import org.apache.logging.log4j.LogManager;import org.apache.logging.log4j.Logger;import lombok.NonNull;import java.util.List;import java.util.Objects;import com.gamerparadise.activity.converter.GamesActivityConverter;import com.gamerparadise.activity.dto.GameActivityDTO;import com.gamerparadise.activity.dto.UploadGameActivityInputDTO;import com.gamerparadise.component.GamesComponent;import com.gamerparadise.component.dto.GameComponentDTO;import com.gamerparadise.component.dto.UploadGameComponentInputDTO;@RestController@RequestMapping("/games")public class GamesActivity {	@Autowired	private GamesActivityConverter gamesActivityConverter;	@Autowired	private GamesComponent gamesComponent;	private static final Logger logger = LogManager.getLogger(GamesActivity.class);	@GetMapping("")	public List<GameActivityDTO> getGames(		@RequestParam(name="franchiseId",required=true) Integer franchiseId,		@RequestParam(name="gameId",required=false) Integer gameId) {		logger.info("Beginning to process getGames for game ID {}{}", gameId.toString(), Objects.isNull(franchiseId) ? "" : " and for franchise ID" + franchiseId.toString());		final List<GameComponentDTO> getGamesComponentOutput = gamesComponent.getGames(franchiseId, gameId);		final List<GameActivityDTO> convertedOutput = getGamesComponentOutput			.stream()			.map((game) -> gamesActivityConverter.convertGameComponentDTOToActivityDTO(game))			.toList();		logger.info("Finished fetching {} games(s)", convertedOutput.size());		return convertedOutput;	}	@PostMapping("")	public void uploadGame(@NonNull @RequestBody UploadGameActivityInputDTO input) {		logger.info("Beginning to process uploadGame with input {}", input);		return;	}}